const soloRender = false;
if (soloRender) {
  require('./frame_processor.js');
}

function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  if (!soloRender) { return; }

  background('#d8e3d2');
  brush.fillBleed(0.6);
  brush.circle(200, 200, 100);

  brush.fillBleed(0.8);
  brush.beginShape(curvature);
  brush.vertex(100, 150);
  brush.vertex(100, 250);
  brush.vertex(120, 250);
  brush.vertex(120, 200);
  brush.endShape(true);

  brush.fillBleed(0.8);
  brush.beginShape(curvature);
  brush.vertex(180, 150);
  brush.vertex(180, 250);
  brush.vertex(200, 250);
  brush.vertex(200, 200);
  brush.endShape(true);

  brush.fillBleed(0.95);
  brush.beginShape(curvature);
  brush.vertex(120, 50);
  brush.vertex(140, 50);
  brush.vertex(150, 70);
  brush.vertex(160, 70);
  brush.endShape(true);

  brush.fillBleed(0.95);
  brush.beginShape(curvature);
  brush.vertex(160, 50);
  brush.vertex(180, 50);
  brush.vertex(190, 70);
  brush.vertex(190, 70);
  brush.endShape(true);
}
