  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // painting goes here
  brush.fill("#c8e6c3", 100); // Sky
  brush.fill("#e08a72", 250); // Horizon
  brush.fill("#386363", 0);  // Hot little grass
  brush.fill("#999999", 50);  // Material 
  brush.fill("#999999", 30);  // Gravitation
  brush.fill("#666666", 50);  // Radial
  brush.fill("#8e7777", 60);  // Shadow

  brush.beginShape();
  brush.vertex(0, 100);
  brush.vertex(400, 350);
  brush.vertex(200, 500);
  brush.vertex(0, 350);
  brush.endShape(true);
  brush.beginPath();
  brush.arc(200, 200, 50, 0, 360); // Sun
  brush.closePath(); 
  brush.fill("#ffffff");
  brush.stroke("#cc9900");
  brush.fill("#ffffff", 50);
  brush.fill("#cc9900", 100);
  brush.fill("#f8c336", 25);
  brush.fill("#a3851b", 20);
  brush.fill("#ff0000", 100);
}

