Here's how you could use the `brush` library to paint a sunset over green hills. This example uses the `fill` method to paint the sky, then the `fillTexture` and `fill` methods to paint the hills:

```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#7c977d", 200);
  brush.fillBleed(0.1);
  brush.fill("#336633", 100);
  brush.fillTexture(0.5, 20);
  brush.endShape(true);

  // Grass
  brush.fill("#b0e38e", 200);
  brush.fillBleed(0.2);
  brush.fill("#90a868", 200);
  brush.fillTexture(0.2, 20);
  brush.vertex(0, 0);
  brush.vertex(0, 400);
  brush.vertex(200, 400);
  brush.vertex(200, 0);
  brush.endShape(false);
}
