```javascript
function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // 1st Brush - Sky - Blue
  brush.fill("#7d79a0", 30);
  brush.circle(0, 400, 250);  // 0, 400 point is top left of hill 
  brush.endShape(true);

  // 2nd Brush - Desert Sand - Light yellow
  brush.fill("#f3c675", 60);
  brush.circle(100, 400, 50);
  brush.endShape(true);

  // 3rd Brush - Gold Dot - Light Gold
  brush.fill("#f7e3c5", 70);
  brush.circle(200, 200, 20);
  brush.vertex(250, 180);
  brush.vertex(300, 200);
  brush.vertex(250, 220);
  brush.endShape(true);

  // 4th Brush - Desert Sand - Golden Sand
  brush.fill("#f3c675", 30);
  brush.circle(200, 300, 50);
  brush.endShape(true);

  // 5th Brush - Grass - Lawn Green
  brush.fill("#a5b38c", 30);
  brush.circle(200, 320, 20);
  brush.vertex(180, 300);
  brush.vertex(210, 320);
  brush.vertex(190, 340);
  brush.endShape(true);

  // 6th Brush - Corn Root - Brown 
  brush.fill("#a5a59a", 30);
  brush.circle(200, 360, 20);
  brush.vertex(180, 360);
  brush.vertex(210, 360);
  brush.vertex(190, 380);
  brush.endShape(true);

  // 7th Brush - Smoke - Blue
  brush.fill("#5f6693", 30);
  brush.circle(200, 400, 20);
  brush.endShape(true);
}
